"""SAMPLE classroom data, so a dashboard is not an empty page during an evaluation.

**This is invented.** It is generated by a simple, seeded rule and written to the same tables as
real data, but every row is marked: tap and feedback ids start with `demo-`, and sample classrooms
are coded `demo-...`. Every screen that shows it says so, and an admin can switch it off or delete
it (`DELETE /api/v1/insights/sample-data`). It is deliberately plain: no improving trend, no
testimonials, no free-text comments, so nothing here can be mistaken for evidence of impact. Real
results come from real phones (the player's taps, attendance and feedback) and from the
user-testing log.
"""

import random
from datetime import UTC, date, datetime, timedelta

from sqlalchemy import delete, func, select
from sqlalchemy.orm import Session

from app.models import CatchupCall, LessonFeedback, SyncEvent

PREFIX = "demo-"

# (code, episode slug, children on the roll, how well the class usually follows)
CLASSROOMS = [
    ("demo-chn-g1-a", "g1-numbers-to-20-chennai-migrant", 28, 0.52),
    ("demo-chn-g1-b", "g1-numbers-to-20-chennai-migrant", 31, 0.44),
    ("demo-chn-g1-c", "g1-numbers-to-20-chennai-migrant", 24, 0.36),
    ("demo-chn-g3-a", "g3-place-value-hundreds-chennai-migrant", 30, 0.58),
    ("demo-chn-g3-b", "g3-place-value-hundreds-chennai-migrant", 27, 0.47),
    ("demo-mdu-g3-a", "g3-place-value-hundreds-madurai-tamil", 26, 0.62),
    ("demo-mdu-g3-b", "g3-place-value-hundreds-madurai-tamil", 29, 0.50),
    ("demo-mdu-g3-c", "g3-place-value-hundreds-madurai-tamil", 22, 0.31),
]
SEGMENTS = {
    "g1-numbers-to-20-chennai-migrant": ["s1", "s2", "s3", "s4"],
    "g3-place-value-hundreds-chennai-migrant": ["s1", "s2", "s3", "s4", "s5"],
    "g3-place-value-hundreds-madurai-tamil": ["s1", "s2", "s3", "s4"],
}
# Some parts are harder than others, for every class alike (added to the chance of "Few got it").
HARDER = {"s1": -0.04, "s2": 0.0, "s3": 0.09, "s4": 0.05, "s5": 0.12}
TAGS = [
    "clear",
    "too fast",
    "too slow",
    "kids engaged",
    "needs more examples",
    "audio unclear",
    "good local examples",
]
WEEKS = 6


def _school_days(today: date, weeks: int) -> list[date]:
    """The Tuesdays and Thursdays of the last `weeks` weeks, up to yesterday."""
    days = [today - timedelta(days=n) for n in range(1, weeks * 7 + 1)]
    return sorted(d for d in days if d.weekday() in (1, 3))


def remove(db: Session) -> None:
    db.execute(delete(SyncEvent).where(SyncEvent.event_id.like(f"{PREFIX}%")))
    db.execute(delete(LessonFeedback).where(LessonFeedback.event_id.like(f"{PREFIX}%")))
    db.execute(delete(CatchupCall).where(CatchupCall.classroom_id.like(f"{PREFIX}%")))
    db.commit()


def counts(db: Session) -> dict[str, int]:
    return {
        "taps": db.scalar(select(func.count()).where(SyncEvent.event_id.like(f"{PREFIX}%"))) or 0,
        "calls": db.scalar(select(func.count()).where(CatchupCall.classroom_id.like(f"{PREFIX}%")))
        or 0,
        "feedback": db.scalar(
            select(func.count()).where(LessonFeedback.event_id.like(f"{PREFIX}%"))
        )
        or 0,
    }


def load(db: Session, today: date | None = None) -> dict[str, int]:
    """Replaces any earlier sample data with a fresh, deterministic set; returns the counts."""
    remove(db)
    today = today or datetime.now(UTC).date()
    for code, episode, roll, strength in CLASSROOMS:
        for day in _school_days(today, WEEKS):
            rng = random.Random(
                f"{code}-{day.isoformat()}"
            )  # the same days always give the same rows
            start = datetime(day.year, day.month, day.day, 4, 30, tzinfo=UTC) + timedelta(
                minutes=rng.randint(0, 90)
            )
            for i, seg in enumerate(SEGMENTS[episode]):
                p_most = min(
                    0.9, max(0.1, strength - HARDER.get(seg, 0) + rng.uniform(-0.07, 0.07))
                )
                p_few = (1 - p_most) * rng.uniform(0.35, 0.55)
                roll_ = rng.random()
                tap = "most" if roll_ < p_most else "few" if roll_ > 1 - p_few else "some"
                auto = (
                    rng.random() < 0.08
                )  # now and then nobody taps and the 10 s fallback plays Core
                db.add(
                    SyncEvent(
                        event_id=f"{PREFIX}{code[len(PREFIX) :]}-{day:%Y%m%d}-{seg}",
                        episode_id=episode,
                        segment_id=seg,
                        tap="some" if auto else tap,
                        auto=auto,
                        at=start + timedelta(minutes=2 * i),
                        classroom_id=code,
                    )
                )
            if rng.random() < 0.6:  # most plays get a rating, none gets a comment
                rating = rng.choices(
                    [3, 4, 5], weights=[2 + 6 * (1 - strength), 4, 3 + 5 * strength]
                )[0]
                db.add(
                    LessonFeedback(
                        event_id=f"{PREFIX}fb-{code[len(PREFIX) :]}-{day:%Y%m%d}",
                        episode_id=episode,
                        classroom_id=code,
                        rating=rating,
                        tags=sorted(rng.sample(TAGS, k=rng.randint(0, 3))),
                        comment="",
                        at=start + timedelta(minutes=12),
                    )
                )
            absent = sorted(
                rng.sample(range(1, roll + 1), k=min(roll, rng.choice([0, 1, 1, 2, 3])))
            )
            for student in absent:
                age_days = (today - day).days
                state = rng.random()
                status, outcome, plays, missed = "queued", None, 0, 0
                if age_days >= 2:
                    if state < 0.72:
                        status, outcome, plays = (
                            "completed",
                            rng.choices(["understood", "help"], weights=[78, 22])[0],
                            rng.randint(1, 2),
                        )
                    else:
                        status, missed = "no_response", rng.randint(0, 2)
                stamp = start + timedelta(hours=10)
                exists = db.scalar(
                    select(CatchupCall.id).where(
                        CatchupCall.classroom_id == code,
                        CatchupCall.student_ref == str(student),
                        CatchupCall.episode_slug == episode,
                    )
                )
                if exists:
                    continue  # the same child can only be called once per lesson
                db.add(
                    CatchupCall(
                        classroom_id=code,
                        student_ref=str(student),
                        episode_slug=episode,
                        status=status,
                        outcome=outcome,
                        plays=plays,
                        missed=missed,
                        created_at=stamp,
                        updated_at=stamp,
                    )
                )
    db.commit()
    return counts(db)
